import React from 'react';
import { describe, test, expect, vi, afterEach } from 'vitest';
import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { ChakraProvider } from '@chakra-ui/react';
import { IntlProvider } from 'react-intl';
import theme from 'app/theme';
import { useMegaMenuOpenReporter } from 'app/hooks/useMegaMenuOpenReporter';
import { useDrawerMenuState } from 'app/hooks/useDrawerMenuState';
import { useWishList } from '@salesforce/retail-react-app/app/hooks/use-wish-list';
import Header from '.';

// LeftBar/RightBar are single-parent internal components with no test/story of their own
// (per components.md, their coverage lives via the header's own assembly) and both pull in
// the base SFCC icons barrel, which has a top-level side effect that throws under Vitest
// (see testing.md's "Known gap: ZimmIcon throws under Vitest"). Mocked out at the smallest
// surface that keeps Header's own render tree assertable — but, unlike a bare stub, this
// surface exposes `menuExpanded` as text and wires the SFCC-96/97 handler props to buttons, so
// both the "Header mega-menu open state" and "Header mobile drawer state" suites below can
// assert on Header's own wiring contract (does it derive the right menuExpanded value, does it
// call the right handler) without needing LeftBar/RightBar's real icon rendering — matching
// testing.md's "mock the smallest surface that keeps this component's own contract assertable"
// guidance.
vi.mock('./leftBar', () => ({
  // Real LeftBar renders exactly one menu-control button whose handler swaps by
  // menuExpanded (hamburger/onMenuClick, X/onMenuClick toggle, back-chevron/onBack) — this
  // mock mirrors that same single-button shape rather than adding a second always-present
  // button, so keyboard tab order here matches the real component. Still renders `children` —
  // needed by the mega-menu open-state suite below, which injects a MegaMenuOpenContext
  // consumer through Header's `children` prop the same way the real ListMenu does.
  LeftBar: ({
    onMenuClick,
    menuExpanded,
    onBack,
    children,
  }: {
    onMenuClick?: () => void;
    menuExpanded?: string;
    onBack?: () => void;
    children?: React.ReactNode;
  }) => (
    <div data-testid="left-bar-stub" data-menu-expanded={menuExpanded}>
      <button onClick={menuExpanded === 'mobileL2' ? onBack : onMenuClick}>menu-or-back-click</button>
      {children}
    </div>
  ),
}));
vi.mock('./rightBar', () => ({
  RightBar: ({
    menuExpanded,
    onClose,
    hasWishlistItems,
  }: {
    menuExpanded?: string;
    onClose?: () => void;
    hasWishlistItems?: boolean;
  }) => (
    <div
      data-testid="right-bar-stub"
      data-menu-expanded={menuExpanded ?? 'closed'}
      data-has-wishlist-items={String(!!hasWishlistItems)}
    >
      <button type="button" onClick={onClose}>
        close-click
      </button>
    </div>
  ),
}));

// navLinks pulls AccountIcon/HeartIcon/etc. from the same base icons barrel — same throw,
// same smallest-surface fix. The real link list isn't relevant to the logo either.
vi.mock('@salesforce/retail-react-app/app/pages/account/constant', () => ({
  navLinks: [],
}));

vi.mock('@salesforce/retail-react-app/app/hooks/use-current-basket', () => ({
  useCurrentBasket: () => ({ derivedData: { totalItems: 0 }, data: undefined }),
}));

vi.mock('@salesforce/retail-react-app/app/hooks/use-wish-list', () => ({
  useWishList: vi.fn(() => ({ data: undefined })),
}));
const mockUseWishList = vi.mocked(useWishList);

vi.mock('@salesforce/commerce-sdk-react', () => ({
