84	    test('distinct timestamps resolve the same way whichever order they arrive in', () => {
85	      const older = entry('older', ['ZimmermannUS'], '2026-01-01T00:00:00.000Z');
86	      const newer = entry('newer', ['ZimmermannUS'], '2026-06-01T00:00:00.000Z');
87	      expect(pickMostSpecificByRegion([newer, older], 'ZimmermannUS')).toBe(newer);
88	      // Previously the warn lived inside the `candidateUpdatedAt > bestUpdatedAt` branch, so a tie
89	      // already arriving newest-first resolved silently. Asserting it here is what pins that.
90	      expect(console.warn).toHaveBeenCalledTimes(1);
91	    });
92	
93	    // The three cases below were invisible to this suite before: the test above only used
94	    // *distinct* timestamps, which is the one arrangement that was already order-independent.
95	    test('identical timestamps resolve by sys.id, not by input order', () => {
96	      const alpha = entry('alpha', ['ZimmermannUS'], '2026-06-01T00:00:00.000Z');
97	      const beta = entry('beta', ['ZimmermannUS'], '2026-06-01T00:00:00.000Z');
98	      expect(pickMostSpecificByRegion([alpha, beta], 'ZimmermannUS')).toBe(alpha);
99	      expect(pickMostSpecificByRegion([beta, alpha], 'ZimmermannUS')).toBe(alpha);
100	    });
101	
102	    test('absent timestamps resolve by sys.id, not by input order', () => {
103	      const alpha = entry('alpha', ['ZimmermannUS']);
104	      const beta = entry('beta', ['ZimmermannUS']);
105	      expect(pickMostSpecificByRegion([alpha, beta], 'ZimmermannUS')).toBe(alpha);
106	      expect(pickMostSpecificByRegion([beta, alpha], 'ZimmermannUS')).toBe(alpha);
107	    });
