109	    // [alpha, beta], not [beta, alpha]: in the latter the candidate wins on sys.id, so the warn
110	    // fires even if it were still nested inside the comparison. Only the losing-candidate order
111	    // distinguishes "warns on every tie" from "warns when the candidate happens to win".
112	    test('warns on a tie even when the incumbent keeps the win', () => {
113	      const alpha = entry('alpha', ['ZimmermannUS'], '2026-06-01T00:00:00.000Z');
114	      const beta = entry('beta', ['ZimmermannUS'], '2026-06-01T00:00:00.000Z');
115	      expect(pickMostSpecificByRegion([alpha, beta], 'ZimmermannUS')).toBe(alpha);
116	      expect(console.warn).toHaveBeenCalledTimes(1);
117	    });
