130	      const alpha = entry('alpha');
131	      const beta = entry('beta');
132	      expect(pickMostSpecificByRegion([beta, alpha], 'ZimmermannUS')).toBe(alpha);
133	      expect(console.warn).toHaveBeenCalledTimes(1);
