describe('filterByRegion', () => {
  test('keeps a global (unscoped) entry for any site', () => {
    const global = entry('global');
    expect(filterByRegion([global], 'ZimmermannUS')).toEqual([global]);
  });

  test('keeps a global entry with an explicitly empty regions array', () => {
    const global = entry('global', []);
    expect(filterByRegion([global], 'ZimmermannUS')).toEqual([global]);
  });

  test('keeps an entry whose regions include the current site', () => {
    const us = entry('us', ['ZimmermannUS']);
    expect(filterByRegion([us], 'ZimmermannUS')).toEqual([us]);
  });

  test('drops an entry scoped to other sites only', () => {
    const au = entry('au', ['ZimmermannAU']);
    expect(filterByRegion([au], 'ZimmermannUS')).toEqual([]);
  });

  test('keeps multiple non-conflicting eligible entries', () => {
    const global = entry('global');
    const us = entry('us', ['ZimmermannUS']);
    const au = entry('au', ['ZimmermannAU']);
    expect(filterByRegion([global, us, au], 'ZimmermannUS')).toEqual([global, us]);
