    // *distinct* timestamps, which is the one arrangement that was already order-independent.
    test('identical timestamps resolve by sys.id, not by input order', () => {
      const alpha = entry('alpha', ['ZimmermannUS'], '2026-06-01T00:00:00.000Z');
      const beta = entry('beta', ['ZimmermannUS'], '2026-06-01T00:00:00.000Z');
      expect(pickMostSpecificByRegion([alpha, beta], 'ZimmermannUS')).toBe(alpha);
      expect(pickMostSpecificByRegion([beta, alpha], 'ZimmermannUS')).toBe(alpha);
    });

    test('absent timestamps resolve by sys.id, not by input order', () => {
      const alpha = entry('alpha', ['ZimmermannUS']);
      const beta = entry('beta', ['ZimmermannUS']);
      expect(pickMostSpecificByRegion([alpha, beta], 'ZimmermannUS')).toBe(alpha);
      expect(pickMostSpecificByRegion([beta, alpha], 'ZimmermannUS')).toBe(alpha);
    });

