    // fires even if it were still nested inside the comparison. Only the losing-candidate order
    // distinguishes "warns on every tie" from "warns when the candidate happens to win".
    test('warns on a tie even when the incumbent keeps the win', () => {
      const alpha = entry('alpha', ['ZimmermannUS'], '2026-06-01T00:00:00.000Z');
      const beta = entry('beta', ['ZimmermannUS'], '2026-06-01T00:00:00.000Z');
      expect(pickMostSpecificByRegion([alpha, beta], 'ZimmermannUS')).toBe(alpha);
      expect(console.warn).toHaveBeenCalledTimes(1);
    });

