      const zeta = entry('zeta', ['ZimmermannUS'], '2026-06-01T00:00:00.000Z');
      const alpha = entry('alpha', ['ZimmermannUS'], '2026-01-01T00:00:00.000Z');
      expect(pickMostSpecificByRegion([zeta, alpha], 'ZimmermannUS')).toBe(zeta);
      expect(pickMostSpecificByRegion([alpha, zeta], 'ZimmermannUS')).toBe(zeta);
    });

