    });
  });
});

/**
 * Allow-list guard for hrefs that originate outside the codebase.
 *
 * Anything reaching an `href` from Contentful, a URL parameter, or a prop supplied by a
 * caller we do not control has to pass through here first. `javascript:` and `data:` URLs
 * execute; an authority reference like `//host` silently leaves the site. The `(?![/\\])`
 * lookahead rejects that, including the backslash form — a browser treats `/\host` as `//host`,
 * so a backslash is an authority reference just as much as a second slash is. `e9c2180` closed
 * only the forward-slash half; the backslash and control-character forms stayed open until now.
 *
 * Allow-list rather than deny-list on purpose: a deny-list has to anticipate every scheme,
 * and browsers keep adding them.
 */
// eslint-disable no-control-regex — the control characters ARE the subject here. The rule exists
// to catch them appearing by accident; these are deliberate, and matching them is the whole point
// of the fix. Suppressed at the point of use rather than in .eslintrc, per the escape-hatch
// convention in .claude/rules/typescript.md.
/* eslint-disable no-control-regex */
const C0_OR_SPACE = /^[\u0000-\u0020]+|[\u0000-\u0020]+$/g;
const TAB_LF_CR = /[\u0009\u000a\u000d]/g;
/* eslint-enable no-control-regex */

/**
 * Normalise the way the URL parser will, before testing.
 *
 * The WHATWG parser strips leading and trailing C0-or-space, and removes tab/LF/CR from anywhere
 * in the input, BEFORE it parses. `/\u0009/evil.com` is therefore parsed as `//evil.com`. Testing
 * the raw string means the allow-list checks a different value than the browser resolves — which
 * is exactly how the earlier fix passed its own tests while leaving the hole open.
 *
 * A plain space is deliberately not stripped: the parser percent-encodes it rather than removing
 * it, so `/ /evil.com` resolves on-site and must stay allowed.
 */
const normalise = (href: string): string => href.replace(C0_OR_SPACE, '').replace(TAB_LF_CR, '');

const SAFE_HREF_RE = /^(https?:|tel:|mailto:|#|\/(?![/\\]))/i;

/** True when `href` is safe to render on an anchor. Absent or unsafe values return false. */
export const isSafeHref = (href: string | undefined): boolean => (href ? SAFE_HREF_RE.test(normalise(href)) : false);

/**
 * A single leading `/` is a same-origin relative path that needs the current site/locale prefix
 * from `useMultiSite()`'s `buildUrl()` (see `buildSafeHref`/`useSafeHref`) before it's safe to
 * navigate to — an unprefixed internal path always falls back to the default site.
 *
 * Checks the normalised value, same as `isSafeHref` — a raw, un-normalised check would disagree
 * with `isSafeHref` on a value like a leading-space href (`normalise` strips it, `isSafeHref`
 * allows it), misclassifying a real internal path as external and silently skipping `buildUrl`.
 *
 * Relies on `isSafeHref` having already run: that regex's own negative lookahead is what keeps
 * `//host`/`/\host` (off-site authority references) out of this function's input in practice, so
 * this check only needs to distinguish "internal path" from the other forms `isSafeHref` allows
 * (`https?:`, `tel:`, `mailto:`, `#fragment`) — every one of which must NOT be run through
 * `buildUrl` (it would corrupt an absolute/external URL, or replace an in-page fragment's own
 * page path with just the site prefix).
 */
export const isInternalHref = (href: string): boolean => normalise(href).startsWith('/');

/**
 * Runs `href` through `buildUrl()` only when it's an internal path (see `isInternalHref`) —
 * every other form `isSafeHref` allows is returned unchanged, exactly as given (not normalised —
 * normalising an external/tel/mailto/# value isn't this function's job). `buildUrl` itself
 * receives the *normalised* internal path, not the raw one, so a leading-space href doesn't leak
 * a stray character into the prefixed URL. `buildUrl` is passed in rather than looked up here
 * since this module has no hook of its own; see `useSafeHref`
 * (`overrides/app/hooks/useSafeHref.ts`) for the hook form of this same composition, and for the
 * single place every internal-navigation call site in this app should reach for.
 */
export const buildSafeHref = (href: string, buildUrl: (path: string) => string): string => {
  const normalisedHref = normalise(href);
  return isInternalHref(normalisedHref) ? buildUrl(normalisedHref) : href;
};

import { defineConfig } from 'vitest/config';
import path from 'path';
import react from '@vitejs/plugin-react';

export default defineConfig({
  plugins: [react()],
  test: {
    globals: true,
    environment: 'jsdom',
    setupFiles: ['./vitest.setup.ts'],
    include: ['overrides/**/*.test.ts', 'overrides/**/*.test.tsx'],
    passWithNoTests: true,
    coverage: {
      provider: 'v8',
      // Force-includes every file under overrides/ at 0% if no test ever
      // imports it — without this, coverage only reports on the files the
      // 16 (as of 2026-08-26) existing test files happen to import, which
      // reads as a misleadingly high percentage of a much smaller universe
      // than "overrides/" as a whole (added at the developer's explicit
      // request for whole-tree visibility, not just tested-file visibility).
      all: true,
      include: ['overrides/**/*.{ts,tsx}'],
      exclude: [
        'overrides/**/*.test.{ts,tsx}',
        'overrides/**/*.stories.{ts,tsx}',
        'overrides/**/*.css.ts',
        'overrides/**/*.d.ts',
      ],
      reporter: ['text', 'json-summary', 'html'],
    },
  },
  resolve: {
    // Keep in sync with babel.config.js, tsconfig.json, .storybook/main.js
    // (jest.config.js's aliases are separate — for @salesforce/pwa-kit-dev internals only)
    alias: {
      '~': path.resolve(__dirname),
      app: path.resolve(__dirname, 'overrides/app'),
      // @salesforce/commerce-sdk-react@5.2.0's published package.json declares
      // main: "dist/index.js", but the published tarball has no dist/ at all —
      // the real entry file is index.js at the package root (confirmed by
      // unpacking the npm tarball directly; same defect persists through at
      // least 5.4.0). Node/webpack resolve this fine because their module
      // resolution falls back to a package's root index.js when `main` doesn't
      // exist; Vite/Vitest's resolver has no such fallback and fails with
      // "Failed to resolve entry for package". The same broken-`main` defect
      // also breaks Vite/Vitest's resolution of this package's subpath exports
      // (`/components`, `/page-designer`) even though each has a real
      // index.js on disk and Node/webpack resolve them fine — an earlier
      // revision of this comment claimed subpaths "resolve normally,
      // untouched by this alias"; that was wrong, disproven when
      // overrides/app/components/_app/index.tsx (SFCC-863) became the first
      // file in overrides/ to import either subpath and its test failed to
      // resolve them. Add a new exact-match entry here for each subpath as
      // one gets a real consumer, rather than trying to express this as a
      // single prefix/RegExp alias.
      // Order matters: Vite's alias matching treats a bare-specifier key as a prefix match
      // too (`importee === key || importee.startsWith(key + '/')`), so the subpath entries
      // must come before the bare '@salesforce/commerce-sdk-react' entry below or that
      // broader entry wins first and mis-resolves the subpath.
      '@salesforce/commerce-sdk-react/components': path.resolve(
        __dirname,
        'node_modules/@salesforce/commerce-sdk-react/components/index.js',
      ),
      '@salesforce/commerce-sdk-react/page-designer': path.resolve(
        __dirname,
        'node_modules/@salesforce/commerce-sdk-react/page-designer/index.js',
      ),
      '@salesforce/commerce-sdk-react': path.resolve(__dirname, 'node_modules/@salesforce/commerce-sdk-react/index.js'),
    },
  },
});

