  getConfig: vi.fn(),
}));

vi.mock('@salesforce/pwa-kit-react-sdk/ssr/universal/utils', async (importOriginal) => {
  const actual = await importOriginal<typeof import('@salesforce/pwa-kit-react-sdk/ssr/universal/utils')>();
  return { ...actual, getRouterBasePath: vi.fn(() => '') };
