  siteAliases: { ZimmermannEUit: 'it-eu', ZimmermannEUfr: 'fr-eu' },
  defaultSite: 'ZimmermannEUit',
  sites: [
    {
      id: 'ZimmermannEUit',
      l10n: { defaultLocale: 'it', defaultCurrency: 'EUR', supportedLocales: [{ id: 'it', preferredCurrency: 'EUR' }] },
    },
    {
      id: 'ZimmermannEUfr',
      l10n: { defaultLocale: 'fr', defaultCurrency: 'EUR', supportedLocales: [{ id: 'fr', preferredCurrency: 'EUR' }] },
    },
  ],
};

const buildUrlStub = () => vi.fn((path: string, siteRef?: string, localeRef?: string) => `/${siteRef}${path}`);

describe('crossSiteUrl', () => {
  beforeEach(() => {
    vi.mocked(getConfig).mockReturnValue({ app: mockAppConfig } as never);
    vi.mocked(getRouterBasePath).mockReturnValue('');
