    expect(result).toBe('/fr-eu/product/123');
  });

  test('drops refine by default but keeps other query params', () => {
    const buildUrl = buildUrlStub();
    crossSiteUrl('fr-eu', 'fr', buildUrl, {
      location: { pathname: '/it-eu/category/dresses', search: '?refine=c_refinementColour%3Dnero&limit=25' },
    });
    const [pathArg] = buildUrl.mock.calls[0] as [string];
    expect(pathArg).not.toContain('refine');
    expect(pathArg).toContain('limit=25');
  });

  test('a caller-supplied disallowParams list overrides the default instead of adding to it', () => {
    const buildUrl = buildUrlStub();
    crossSiteUrl('fr-eu', 'fr', buildUrl, {
      location: { pathname: '/it-eu/category/dresses', search: '?refine=c_refinementColour%3Dnero&limit=25' },
      disallowParams: ['limit'],
    });
    const [pathArg] = buildUrl.mock.calls[0] as [string];
    // refine is NOT in the override list, so it must survive; limit was explicitly disallowed.
    expect(pathArg).toContain('refine');
    expect(pathArg).not.toContain('limit');
  });

  test('strips both the base path and the current site alias before building the new URL', () => {
    vi.mocked(getRouterBasePath).mockReturnValue('/mobify-base');
    const buildUrl = buildUrlStub();
    crossSiteUrl('fr-eu', 'fr', buildUrl, {
      location: { pathname: '/mobify-base/it-eu/product/123', search: '' },
    });
    const [pathArg] = buildUrl.mock.calls[0] as [string];
    expect(pathArg).toBe('/product/123');
    expect(pathArg).not.toContain('mobify-base');
    expect(pathArg).not.toContain('it-eu');
  });

  test('collapses a bare site-root path to "/" rather than an empty string', () => {
    const buildUrl = buildUrlStub();
    crossSiteUrl('fr-eu', 'fr', buildUrl, {
      location: { pathname: '/it-eu', search: '' },
    });
    const [pathArg] = buildUrl.mock.calls[0] as [string];
    expect(pathArg).toBe('/');
    expect(pathArg).not.toBe('');
    expect(pathArg).not.toMatch(/\/\//);
  });

  test('DEFAULT_DISALLOWED_PARAMS is exactly ["refine"]', () => {
    expect(DEFAULT_DISALLOWED_PARAMS).toEqual(['refine']);
  });
});

