import { beforeEach, describe, expect, test, vi } from 'vitest';
import { getRouterBasePath } from '@salesforce/pwa-kit-react-sdk/ssr/universal/utils';
import { getConfig } from '@salesforce/pwa-kit-runtime/utils/ssr-config';
import { DEFAULT_DISALLOWED_PARAMS, crossSiteUrl } from './crossSiteUrl';

// Mirrors the vendor's own `url.test.js` technique (node_modules/@salesforce/retail-react-app/
// app/utils/url.test.js) for testing `getPathWithLocale`, the function this one is modelled on:
// mock `getConfig` with a realistic site list so the real `getParamsFromPath`/
// `removeBasePathFromPath` helpers this file reuses run against real Zimmermann EU-domestic
// site data, rather than re-testing the SDK's own site/locale-matching regex by hand.
vi.mock('@salesforce/pwa-kit-runtime/utils/ssr-config', () => ({
  getConfig: vi.fn(),
}));

vi.mock('@salesforce/pwa-kit-react-sdk/ssr/universal/utils', async (importOriginal) => {
  const actual = await importOriginal<typeof import('@salesforce/pwa-kit-react-sdk/ssr/universal/utils')>();
  return { ...actual, getRouterBasePath: vi.fn(() => '') };
});

// A minimal, real subset of config/sites.overlay.js's EU-domestic shape (id/alias/locale) —
// enough for the real getParamsFromPath's site/locale-matching regex to recognise 'it-eu'/'fr-eu'
// as site aliases, without duplicating the whole live config/sites.js merge.
const mockAppConfig = {
  url: { locale: 'path', site: 'path', showDefaults: true },
  siteAliases: { ZimmermannEUit: 'it-eu', ZimmermannEUfr: 'fr-eu' },
  defaultSite: 'ZimmermannEUit',
  sites: [
    {
      id: 'ZimmermannEUit',
      l10n: { defaultLocale: 'it', defaultCurrency: 'EUR', supportedLocales: [{ id: 'it', preferredCurrency: 'EUR' }] },
    },
    {
      id: 'ZimmermannEUfr',
      l10n: { defaultLocale: 'fr', defaultCurrency: 'EUR', supportedLocales: [{ id: 'fr', preferredCurrency: 'EUR' }] },
    },
  ],
};

const buildUrlStub = () => vi.fn((path: string, siteRef?: string, localeRef?: string) => `/${siteRef}${path}`);

describe('crossSiteUrl', () => {
  beforeEach(() => {
    vi.mocked(getConfig).mockReturnValue({ app: mockAppConfig } as never);
    vi.mocked(getRouterBasePath).mockReturnValue('');
  });

  test('preserves the path across a site switch', () => {
    const buildUrl = buildUrlStub();
    const result = crossSiteUrl('fr-eu', 'fr', buildUrl, {
      location: { pathname: '/it-eu/product/123', search: '' },
    });
    expect(buildUrl).toHaveBeenCalledWith('/product/123', 'fr-eu', 'fr');
    expect(result).toBe('/fr-eu/product/123');
  });

  test('drops refine by default but keeps other query params', () => {
    const buildUrl = buildUrlStub();
    crossSiteUrl('fr-eu', 'fr', buildUrl, {
      location: { pathname: '/it-eu/category/dresses', search: '?refine=c_refinementColour%3Dnero&limit=25' },
    });
    const [pathArg] = buildUrl.mock.calls[0] as [string];
    expect(pathArg).not.toContain('refine');
    expect(pathArg).toContain('limit=25');
  });

  test('a caller-supplied disallowParams list overrides the default instead of adding to it', () => {
    const buildUrl = buildUrlStub();
    crossSiteUrl('fr-eu', 'fr', buildUrl, {
      location: { pathname: '/it-eu/category/dresses', search: '?refine=c_refinementColour%3Dnero&limit=25' },
      disallowParams: ['limit'],
    });
    const [pathArg] = buildUrl.mock.calls[0] as [string];
    // refine is NOT in the override list, so it must survive; limit was explicitly disallowed.
    expect(pathArg).toContain('refine');
    expect(pathArg).not.toContain('limit');
  });

  test('strips both the base path and the current site alias before building the new URL', () => {
    vi.mocked(getRouterBasePath).mockReturnValue('/mobify-base');
    const buildUrl = buildUrlStub();
    crossSiteUrl('fr-eu', 'fr', buildUrl, {
      location: { pathname: '/mobify-base/it-eu/product/123', search: '' },
    });
    const [pathArg] = buildUrl.mock.calls[0] as [string];
    expect(pathArg).toBe('/product/123');
    expect(pathArg).not.toContain('mobify-base');
    expect(pathArg).not.toContain('it-eu');
  });

  test('collapses a bare site-root path to "/" rather than an empty string', () => {
    const buildUrl = buildUrlStub();
    crossSiteUrl('fr-eu', 'fr', buildUrl, {
      location: { pathname: '/it-eu', search: '' },
    });
    const [pathArg] = buildUrl.mock.calls[0] as [string];
    expect(pathArg).toBe('/');
    expect(pathArg).not.toBe('');
    expect(pathArg).not.toMatch(/\/\//);
  });

  test('DEFAULT_DISALLOWED_PARAMS is exactly ["refine"]', () => {
    expect(DEFAULT_DISALLOWED_PARAMS).toEqual(['refine']);
  });
});

